UserObject.mermaidData:
{
  "data": "classDiagram

class Client {
    +int id
    +string name
    +string email
    +string phone
}

class Immobile {
    +int id
    +string code
    +TypeImmobile type_item
    +string address
    +decimal price
    +boolean is_locate
}

class ImmobileImage {
    +int id
    +image image
}

class RegisterLocation {
    +int id
    +datetime dt_start
    +datetime dt_end
    +date create_at
}

class TypeImmobile {
    <<enumeration>>
    APARTAMENTO
    KITNET
    CASA
}

Client "1" --> "0..*" RegisterLocation : realiza

Immobile "1" --> "0..*" RegisterLocation : possui

Immobile "1" --> "0..*" ImmobileImage : contém

Immobile --> TypeImmobile",
  "config": null
}

